// ==========================================
// RENDER KATALOG
// ==========================================
const grid = document.getElementById("catalogGrid");

function renderCatalog(category) {
  const filtered =
    category === "all"
      ? catalogData
      : catalogData.filter((item) => item.cat === category);

  if (filtered.length === 0) {
    grid.innerHTML = "";
    document.getElementById("emptyState").classList.remove("hidden");
    return;
  }
  document.getElementById("emptyState").classList.add("hidden");

  grid.innerHTML = filtered
    .map(
      (item, i) => `
        <div class="catalog-card card-out" style="transition-delay:${i * 60}ms">
            <div class="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl border border-gray-100 hover:border-brand/40 transition-all duration-300 group h-full flex flex-col">
                <div class="relative h-48 overflow-hidden">
                    <img src="${item.img}" alt="${item.name}" class="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" loading="lazy" onerror="this.onerror=null;this.src='images/about.jpg'">
                    <div class="absolute inset-0 bg-gradient-to-t from-ink-900/60 via-transparent to-transparent"></div>
                    <div class="absolute top-3 left-3 bg-brand/90 backdrop-blur-sm text-white text-[11px] font-bold px-3 py-1 rounded-full uppercase tracking-wider">
                        ${item.catLabel}
                    </div>
                    <div class="absolute bottom-3 left-3">
                        <span class="iconify text-white/70 text-3xl" data-icon="${item.icon}"></span>
                    </div>
                </div>
                <div class="p-6 flex flex-col flex-1">
                    <h3 class="text-lg font-bold text-ink-900 mb-2 leading-snug">${item.name}</h3>
                    <p class="text-ink-500 text-sm leading-relaxed mb-5 flex-1">"${item.hook}"</p>
                    ${item.productUrl
                      ? `<a href="${item.productUrl}" target="_blank" rel="noopener noreferrer" class="w-full bg-brand hover:bg-brand-dark text-white font-semibold py-3 rounded-xl transition-all duration-200 flex items-center justify-center gap-2 hover:shadow-lg hover:shadow-brand/20">
                        <span class="iconify" data-icon="mdi:open-in-new"></span>
                        Lihat Produk Kaca Shower
                      </a>`
                      : `<button onclick="askPrice('${item.name.replace(/'/g, "\\'")}')" class="w-full bg-brand hover:bg-brand-dark text-white font-semibold py-3 rounded-xl transition-all duration-200 flex items-center justify-center gap-2 hover:shadow-lg hover:shadow-brand/20">
                        <span class="iconify" data-icon="mdi:whatsapp"></span>
                        Tanya Harga ${item.name.split(" ").slice(0, 2).join(" ")}
                      </button>`}
                </div>
            </div>
        </div>
    `,
    )
    .join("");

  // Animate in
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      document.querySelectorAll(".catalog-card.card-out").forEach((card) => {
        card.classList.remove("card-out");
      });
    });
  });
}

// Initial render
renderCatalog("all");

// ==========================================
// FILTER KATALOG (Tab Switching)
// ==========================================
document.querySelectorAll(".cat-tab").forEach((tab) => {
  tab.addEventListener("click", () => {
    // Update active tab
    document.querySelectorAll(".cat-tab").forEach((t) => {
      t.classList.remove("active", "bg-brand", "text-white");
      t.classList.add("bg-white", "text-ink-600", "border", "border-gray-200");
    });
    tab.classList.add("active", "bg-brand", "text-white");
    tab.classList.remove(
      "bg-white",
      "text-ink-600",
      "border",
      "border-gray-200",
    );

    renderCatalog(tab.dataset.cat);
  });
});

// ==========================================
// WHATSAPP INTEGRATION
// ==========================================
function askPrice(serviceName) {
  const message = encodeURIComponent(
    `Halo tim CV. Satu Atap Karya, saya melihat website Anda dan tertarik untuk konsultasi mengenai **${serviceName}**. Bisa bantu infokan detailnya?`,
  );
  window.open(`https://wa.me/${WA_NUMBER}?text=${message}`, "_blank");
}

// ==========================================
// HERO SLIDER
// ==========================================
const slides = document.querySelectorAll(".hero-slide");
const dots = document.querySelectorAll(".slide-dot");
let currentSlide = 0;
let slideInterval;

slides.forEach((slide, index) => {
  const image = index % 2 === 0 ? "about.jpg" : "CTA BANNER.jpg";
  slide.style.backgroundImage = `url("images/${image}")`;
});

function goToSlide(index) {
  slides[currentSlide].classList.remove("active");
  dots[currentSlide].classList.remove("bg-brand", "w-10");
  dots[currentSlide].classList.add("bg-white/30", "w-6");

  currentSlide = index;

  slides[currentSlide].classList.add("active");
  dots[currentSlide].classList.add("bg-brand", "w-10");
  dots[currentSlide].classList.remove("bg-white/30", "w-6");
}

function nextSlide() {
  goToSlide((currentSlide + 1) % slides.length);
}

function startSlider() {
  slideInterval = setInterval(nextSlide, 5000);
}

dots.forEach((dot) => {
  dot.addEventListener("click", () => {
    clearInterval(slideInterval);
    goToSlide(parseInt(dot.dataset.slide));
    startSlider();
  });
});

startSlider();

